// T-0456 guarding T-0452 (generated by `npm run chat:probe -- --from-trace 2026-10-24.jsonl:3,2026-10-24.jsonl:4 --agent
// shopkeeper`, the live run reach-shopkeeper-cart-amount-haiku-1 in the T-0452 run records): after the fix Haiku 5.5
// browsed with product tiles only, then answered the first add with ONE ConfirmReceipt plus an AmountPicker for the
// line, on the storefront surface. The fix is model-read text, not producer code: the cart-summary index line and the
// shopkeeper surface style. The content leg reads both from the agent content registry the page composes from, so
// reverting either (round 13 cluster U built a hand-made order Card on the browse turn) reds this file.
import { readFileSync } from 'node:fs'
import { expect, it } from 'vitest'
import { AGENT_CONTENT } from '../../../../site/agent-content/registry.gen.ts'
import { parseProbeFixture } from '../model.ts'
import { offlineReplay } from '../trace.ts'

const record = (kind, id) => AGENT_CONTENT.find((r) => r.kind === kind && r.id === id)
const shipped = (turn) => turn.lines.flatMap((l) => JSON.parse(l).updateComponents?.components ?? []).map((c) => c.component)

it('shopkeeper-haiku-cart-receipt: the first add opens one ConfirmReceipt with an AmountPicker, as the shop teaches', async () => {
  expect(record('skill', 'cart-summary')?.frontmatter.description).toMatch(
    /the first add opens ONE ConfirmReceipt bound to the cart lines plus one AmountPicker per line bound to its quantity; never a hand-built Card$/,
  )
  const persona = record('persona', 'shopkeeper')?.body ?? ''
  expect(persona).toMatch(/one buy action, and nothing else yet\. The first item picked opens the order summary on THAT SAME surface/)
  expect(persona).toMatch(/one confirm-and-receipt card of the order lines with the total, plus one number picker per line for its quantity/)
  expect(persona, 'the wording that built a hand-made order card on the browse turn').not.toMatch(/running order summary/)

  const fixture = parseProbeFixture(readFileSync(new URL('./shopkeeper-haiku-cart-receipt.json', import.meta.url), 'utf8'))
  const report = await offlineReplay(fixture, process.cwd())
  expect(report.failed.map((c) => [c.check, c.turn ?? null])).toEqual([])
  expect(shipped(report.records[0])).not.toContain('ConfirmReceipt')
  expect(shipped(report.records[1])).toEqual(expect.arrayContaining(['ConfirmReceipt', 'AmountPicker']))
})
